use std::fmt;

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use time::OffsetDateTime;
use ts_rs::TS;
use uuid::Uuid;
use zeroize::{Zeroize, Zeroizing};

use crate::schema::Timestamp;
use crate::PolicyAttachment;

/// Source of private key material. JSON: `"Generated"` or `"Imported"`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema, TS)]
pub enum KeySource {
    /// Key generated by the signer backend.
    Generated,
    /// Key material imported by an admin (`KeyCreateRequest::Import*`).
    Imported,
}

/// Signing algorithm bound to a vault key. JSON: `"secp256k1"` or `"ed25519"`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema, TS)]
#[serde(rename_all = "snake_case")]
pub enum KeyAlgorithm {
    /// ECDSA over secp256k1, used for every EVM and Tempo action.
    Secp256k1,
    /// Ed25519, used for Solana actions.
    Ed25519,
}

fn default_key_algorithm() -> KeyAlgorithm {
    KeyAlgorithm::Secp256k1
}

/// Public metadata for a vault signing key. Never contains private key material.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema, TS)]
pub struct VaultKey {
    /// Stable key identifier.
    pub id: Uuid,
    /// How the key was created.
    pub source: KeySource,
    /// Signing algorithm used by the key; `"secp256k1"` when absent on input.
    #[serde(default = "default_key_algorithm")]
    pub algorithm: KeyAlgorithm,
    /// Public key as lowercase hex without `0x`: uncompressed SEC1 (`04` + 64
    /// bytes) for secp256k1, the raw 32-byte key for Ed25519.
    pub public_key_hex: String,
    /// Creation timestamp (UTC).
    #[schemars(with = "Timestamp")]
    #[ts(as = "Timestamp")]
    pub created_at: OffsetDateTime,
    /// Operator-chosen display name (API 1.1), for example `"Trading bot"`:
    /// 1 to 32 characters without control characters. Absent when unnamed
    /// (and for keys stored before names existed).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub name: Option<String>,
}

/// Agent key metadata: an agent identity bound to one vault key and a policy attachment.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema, TS)]
pub struct AgentKey {
    /// Stable agent key identifier (sent as `agent_key_id` by agents).
    pub id: Uuid,
    /// Vault key that signs on behalf of this agent.
    pub vault_key_id: Uuid,
    /// Policies that govern this agent's requests.
    pub policies: PolicyAttachment,
    /// Creation timestamp (UTC).
    #[schemars(with = "Timestamp")]
    #[ts(as = "Timestamp")]
    pub created_at: OffsetDateTime,
}

/// Agent authentication material returned at provisioning time.
///
/// The `auth_token` is a bearer credential and must be treated like a secret:
/// it should be stored securely and never logged.
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema, TS)]
pub struct AgentCredentials {
    /// Public metadata for the provisioned agent key.
    pub agent_key: AgentKey,
    /// Secret bearer token required for agent requests (`agent_auth_token`).
    /// Returned only here; the daemon keeps a SHA-256 hash. Opaque string, at
    /// most 16 KiB.
    #[serde(with = "crate::serde_helpers::zeroizing_string")]
    #[schemars(with = "String")]
    #[ts(as = "String")]
    pub auth_token: Zeroizing<String>,
}

impl fmt::Debug for AgentCredentials {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("AgentCredentials")
            .field("agent_key", &self.agent_key)
            .field("auth_token", &"<redacted>")
            .finish()
    }
}

impl AgentCredentials {
    /// Wipes the auth token in place.
    pub fn zeroize_secrets(&mut self) {
        self.auth_token.zeroize();
    }
}
